head.script:
scwin.autoComplete1_onviewchange = function(info) {
    if (info.newValue == "G") {
        autoComplete1.setValue(info.oldValue);
    }
};
scwin._triggerKeyboardEvent = function(el, keyCode) {
    var eventObj = document.createEventObject ?
        document.createEventObject() : document.createEvent("Events");
    if (eventObj.initEvent) {
        eventObj.initEvent("keydown", true, true);
    }
    eventObj.keyCode = keyCode;
    eventObj.which = keyCode;
    el.dispatchEvent ? el.dispatchEvent(eventObj) : el.fireEvent("onkeydown", eventObj);
}
scwin.callFun1 = function() {
    scwin._triggerKeyboardEvent(WebSquare.wUnit.getDomById('autoComplete1_label'), 13);
}
scwin.callFun2 = function() {
    scwin._triggerKeyboardEvent(WebSquare.wUnit.getDomById('autoComplete1_input'), 13);
}
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('autoComplete1').setText('[100] Nt');");
    WebSquare.wUnit.addCommand("set", "scwin.callFun1()");
    WebSquare.wUnit.addCommand("set", "scwin.callFun2()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('autoComplete1').getSelectedIndex() == 0", "false");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.jsonData = [{
            "value": "G",
            "label": "[400] G"
        },
        {
            "value": "Y1",
            "label": "[300] UY"
        },
        {
            "value": "Y2",
            "label": "[200] UY2"
        },
        {
            "value": "N",
            "label": "[100] Nt"
        }
    ];
    dl_select.setJSON(jsonData);
}
